import { TerminalApp } from './Logic.js';
import { TerminalCommands } from './Commands.js';
import { TerminalFS } from './Filesystem.js';
import { TerminalEffects } from './Effects.js';
import './Terminal Styles.css';

export const TerminalModule = {
  TerminalApp,
  TerminalCommands,
  TerminalFS,
  TerminalEffects
