    matches.forEach((name) => {
      while (!name.startsWith(common)) common = common.slice(0, -1);
    });
    if (common.length > partial.length) {
      input.value = `${prefix}${common}`;
      return;
    }
    this.echo(value);
    this.print(matches.map((name) => ({ text: `${name}   `, cls: name.endsWith("/") ? "dir" : "" })));
