    ? { start: "PRESS SPACE OR TAP TO START", over: "GAME OVER - SPACE / ENTER / TAP", hi: "HI" }
    : { start: "PULSA ESPACIO O TOCA PARA EMPEZAR", over: "GAME OVER - ESPACIO / ENTER / TOCA", hi: "HI" };

  const body = [
    ".........#####........",
    "........#######.......",
    ".......###.#####......",
    ".......#########......",
    ".......########.......",
    ".......####...........",
    "#......####...........",
    "#.....########........",
    "###..######..#........",
    ".##########...........",
    ".##########...........",
    "..#########...........",
    "...#######............",
    "....#####.............",
];

const legs = [
  [
    "....##.##.....",
    "....#..#......",
    "....#..##.....",
    "....##........",
  ],
  [
