".....########.........",
"......######..........",
];

const duckLegs = [
  [
    "....##.##.....",
    "....#..#......",
    "....#..##.....",
    "....##........",
  ],
  [
    "....##.##.....",
    "....#..#......",
    "....##.#......",
    ".......##.....",
  ],
];
  const ptero = [
    [
      ".............##..........",
      "...........#####.........",
      "..........######........",
      ".....#...########.......",
      "...###...##########....#..",
      "..####...############.##..",
